import hashlib,pathlib
items=[
('controller-demo.js', 'dc74de1500300879f5fb0a3af1f47dc5048e645f18285a32202eac46d9653b61', '49719ff9a9406b11fcc7ebd0376293de607aeba804a8cec7681dd579367ab4e1', [(77, 77, "\n// Capability data comes from the existing layout, not a controller-name list.\n// Apply once to the shared sample so demo, manual and live inputs agree in 2D/3D.\nexport function stickClickCapabilities(mapping){\n const result={left:false,right:false};\n for(const layer of mapping?.layers||[])if(layer.role==='stick'&&layer.binding?.clickMask){\n  result[layer.binding.axes?.[0]?.startsWith('left_')?'left':'right']=true;\n }\n return result;\n}\nexport function applyStickClickCapabilities(input,capabilities){\n if(!capabilities)return input;\n if(!capabilities.left){input.left.click=false;input.values.set('ls',0);}\n if(!capabilities.right){input.right.click=false;input.values.set('rs',0);}\n return input;\n}\n")]),
('docs/MODEL_CONSISTENCY.md', 'a638b186fea47bb423ba7da4b308a126ff9b088b4d28601910d99ef18e463256', '9b937f549be36a10ab236d78958e4d5100df274bd8477b8ecbe3b39011b962ce', [(35, 36, '- **GameCube C-stick:** the original 2D asset has one C-stick surface rather than two concentric cap regions; its exact cap surface uses the same analog fill, rather than being replaced by invented circles. There are no hardware L3/R3 buttons on the source mapping. The shared display state suppresses click values absent from the actual mapping, including during the demo, without suppressing analog movement. Matrix records mark such absent inputs rather than declaring them hardware-tested.\n')]),
('pbr-lab.js', '0cae6bb2fa950a713d406e794fb4a1474b2567d8509f48ea46caba327c69de6f', '1808571634e71f76c6eee89d93dd8350e9887a5ad2aed306a7d616f8d88b40e5', [(22, 23, "import {ControllerDemo,createControllerState,stickClickCapabilities,applyStickClickCapabilities} from './controller-demo.js';\n"), (160, 161, '      if(entry?.layer.binding?.clickMask){state.manualButtons.set(entry.control,performance.now()+180);scheduleRender();}\n'), (165, 165, '    const reference=[...flatReferences.values()][0];\n    state.stickClicks=stickClickCapabilities(reference?.mapping);\n'), (166, 167, ''), (197, 198, '  return applyStickClickCapabilities(demo.sample(now,{manual:manual?manualInput:null,live:getLiveStickPose()}),state.stickClicks);\n')]),
('tests/final-demo-mechanics.test.mjs', '427232b1cc0834968b3fe50f76ee178ca575f589f3b821cea27708f93c0f27b0', '80714276490c99a5a7de6511828bf2425fc855ccfdc3968845d600ba9214bed0', [(63, 63, "\ntest('the shared display input suppresses stick-clicks absent from the actual layout without suppressing analog motion',async()=>{\n assert.equal(typeof demo.stickClickCapabilities,'function');\n assert.equal(typeof demo.applyStickClickCapabilities,'function');\n for(const [id,left,right]of [['gamecube',false,false],['dualsense',true,true],['joycon_left',true,false],['joycon_right',false,true]]){\n  const mapping=JSON.parse(await read('references/controllers/'+id+'/mapping.json'));\n  const caps=demo.stickClickCapabilities(mapping);\n  assert.deepEqual(caps,{left,right});\n  const input=demo.createControllerState();input.left.x=.8;input.right.y=-.7;\n  input.left.click=input.right.click=true;input.values.set('ls',1);input.values.set('rs',1);\n  assert.equal(demo.applyStickClickCapabilities(input,caps),input);\n  assert.equal(input.left.click,left);assert.equal(input.right.click,right);\n  assert.equal(input.values.get('ls'),left?1:0);assert.equal(input.values.get('rs'),right?1:0);\n  assert.equal(input.left.x,.8);assert.equal(input.right.y,-.7);\n }\n});\n")]),
('tools/capture-model-consistency.mjs', 'fb597f8d67c8f2d7db38c1806010977f0b6d571302f47d86e0a159be74732fcd', '01a9ea5b20e61ca048d1b1d9b7e3e2412204816fe3df747d68c9982e67fd10e8', [(125, 125, "  // Unsupported click values must not become imaginary controls in the\n  // shared displayed sample, including the automatic demo's click sequence.\n  await input({buttons:{ls:1,rs:1},left:[.6,.8],right:[-.8,.6]});\n  const clicks=await page.evaluate(()=>({left:window.__exoPbrLab.input.left.click,right:window.__exoPbrLab.input.right.click,\n    ls:window.__exoPbrLab.input.values.get('ls'),rs:window.__exoPbrLab.input.values.get('rs')}));\n  for(const [side,key]of [['left','ls'],['right','rs']])\n    check(clicks[side]===clickable.includes(key)&&Boolean(clicks[key])===clickable.includes(key),'Unsupported layout click reached 2D/3D',{model:model.id,clicks,clickable});\n  await input({});\n")]),
 ]
for name,before,after,edits in items:
 p=pathlib.Path(name);s=p.read_text();assert hashlib.sha256(s.encode()).hexdigest()==before,name
 lines=s.splitlines(keepends=True)
 for a,b,text in reversed(edits):lines[a:b]=[text]
 s=''.join(lines);assert hashlib.sha256(s.encode()).hexdigest()==after,name
 p.write_text(s)
